protected override void OnModelCreating(ModelBuilder modelBuilder)
{
    // Keep "Discriminator" so existing documents with that property are still found.
    // Default changed to "$type" in EF Core 9.
    modelBuilder.Entity<Blog>().HasDiscriminator<string>("Discriminator");

    // Keep the old compound id format ("Blog|1") so existing documents remain accessible.
    // EF Core 9 changed the default to key-only ids.
    modelBuilder.Entity<Blog>().HasRootDiscriminatorInJsonId(true);

    // HasIndex removed — Cosmos DB provider now throws at startup.
    // Manage indexing via the container's indexing policy instead.
}

